//! Python `str` predicates and `repr()`, from tables generated by Python.

use std::cmp::Ordering;

#[rustfmt::skip]
#[path = "pystr_table.rs"]
mod table;

fn in_table(t: &[(u32, u32)], n: u32) -> bool {
    t.binary_search_by(|&(lo, hi)| {
        if hi < n {
            Ordering::Less
        } else if lo > n {
            Ordering::Greater
        } else {
            Ordering::Equal
        }
    })
    .is_ok()
}

/// `str.isprintable()`.
pub fn is_printable(c: char) -> bool {
    let n = c as u32;
    if n < 0x80 { (0x20..0x7f).contains(&n) } else { !in_table(table::NON_PRINTABLE, n) }
}

/// `str.isalnum()`.
pub fn is_alnum(c: char) -> bool {
    if c.is_ascii() { c.is_ascii_alphanumeric() } else { in_table(table::ALNUM, c as u32) }
}

/// `re`'s `\w` for str patterns.
pub fn is_word(c: char) -> bool {
    c == '_' || is_alnum(c)
}

/// `str.isspace()`.
pub fn is_space(c: char) -> bool {
    matches!(
        c,
        '\t'..='\r'
            | '\x1c'..='\x1f'
            | ' '
            | '\u{85}'
            | '\u{a0}'
            | '\u{1680}'
            | '\u{2000}'..='\u{200a}'
            | '\u{2028}'
            | '\u{2029}'
            | '\u{202f}'
            | '\u{205f}'
            | '\u{3000}'
    )
}

/// `str.strip()`.
pub fn strip(s: &str) -> &str {
    s.trim_matches(is_space)
}

/// `s[:n]` (code points).
pub fn prefix(s: &str, n: usize) -> &str {
    match s.char_indices().nth(n) {
        Some((i, _)) => &s[..i],
        None => s,
    }
}

/// `repr(s)`.
pub fn repr(s: &str) -> String {
    let quote = if s.contains('\'') && !s.contains('"') { '"' } else { '\'' };
    let mut out = String::with_capacity(s.len() + 2);
    out.push(quote);
    for c in s.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '\t' => out.push_str("\\t"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            c if c == quote => {
                out.push('\\');
                out.push(c);
            }
            c if is_printable(c) => out.push(c),
            c => {
                let n = c as u32;
                if n <= 0xff {
                    out.push_str(&format!("\\x{n:02x}"));
                } else if n <= 0xffff {
                    out.push_str(&format!("\\u{n:04x}"));
                } else {
                    out.push_str(&format!("\\U{n:08x}"));
                }
            }
        }
    }
    out.push(quote);
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn repr_matches_python() {
        assert_eq!(repr("it's"), "\"it's\"");
        assert_eq!(repr("a'\"b"), "'a\\'\"b'");
        assert_eq!(
            repr("\u{0}\u{7f}\u{85}\u{a0}é\u{200b}\u{e000}😀\u{e0001}"),
            "'\\x00\\x7f\\x85\\xa0é\\u200b\\ue000😀\\U000e0001'"
        );
    }

    #[test]
    fn predicates() {
        assert!(is_word('²') && is_word('ก') && !is_word('\u{e34}') && !is_word('-'));
        assert_eq!(strip("\x1c a \u{3000}"), "a");
        assert_eq!(prefix("héllo", 2), "hé");
    }
}
